def convert(self, s: str, numRows: int) -> str:
    if numRows == 1:
        return s
    n = len(s)
    cycle = 2 * numRows - 2
    result = []
    for r in range(numRows):
        i = r
        while i < n:
            result.append(s[i])
            if r != 0 and r != numRows - 1:
                diag = i + cycle - 2 * r
                if diag < n:
                    result.append(s[diag])
            i += cycle
    return ''.join(result)

